	protected void CheckCancelAutoOnDiceCastedOnRuneCasted(GameObject source)
	{
		TurnManager instance = ReferenceSingleton<TurnManager>.Instance;
		if (instance.CurrentTurn == instance.PlayerTurn && !ReferenceSingleton<BattleHandler>.Instance.IsSourceEnemy(source) && source != null && cancelAutoOnDiceCastedOnRuneCasted)
		{
			ReferenceSingleton<BattleHandler>.Instance.OnDiceCastedOrOnRuneCasted();
		}
	}

