	public virtual void SetupModdedBattleAction()
	{
	}

	protected void SetupModdedBattleAction(string battleActionName, string moddedDescription, BattleActionInteractionEnum battleActionInteractionEnum, DiceActionLogicsList.DiceActionLogicEnum diceActionLogicEnum, Sprite battleActionSprite)
	{
		base.name = battleActionName;
		diceActionLogic = ReferenceSingleton<ModHelper>.Instance.DiceActionLogicsList.GetDiceActionLogic(diceActionLogicEnum);
		BaseBattleActionData baseBattleActionData = new BaseBattleActionData();
		baseBattleActionData.SetupModdedBaseBattleActionData(moddedDescription, battleActionInteractionEnum);
		SetBaseBattleActionData(baseBattleActionData);
		BattleActionSprite = battleActionSprite;
	}

	protected void SetupModdedBattleAction(string battleActionName, BaseBattleActionData baseBattleActionData, DiceActionLogicsList.DiceActionLogicEnum diceActionLogicEnum, Sprite battleActionSprite)
	{
		base.name = battleActionName;
		diceActionLogic = ReferenceSingleton<ModHelper>.Instance.DiceActionLogicsList.GetDiceActionLogic(diceActionLogicEnum);
		SetBaseBattleActionData(baseBattleActionData);
		BattleActionSprite = battleActionSprite;
	}

	private void SetBaseBattleActionData(BaseBattleActionData baseBattleActionData)
